141: 	private async ValueTask<ValidationResult> ValidateInternalAsync(ValidationContext<T> context, CancellationToken cancellation) {
142: 		var result = new ValidationResult(context.Failures);
143: 		bool shouldContinue = PreValidate(context, result);
144: 
145: 		if (!shouldContinue) {
146: 			if (!result.IsValid && context.ThrowOnFailures) {
147: 				RaiseValidationException(context, result);
