153: 		if (context.InstanceToValidate == null) {
154: 			throw new InvalidOperationException("Cannot pass a null model to Validate/ValidateAsync. The root model must be non-null.");
155: 		}
156: 
157: 		int count = Rules.Count;
158: 
159: 		// Performance: Use for loop rather than foreach to reduce allocations.
160: 		for (int i = 0; i < count; i++) {
161: 			cancellation.ThrowIfCancellationRequested();
162: 			var totalFailures = context.Failures.Count;
163: 
164: 			await Rules[i].ValidateAsync(context, cancellation);
165: 
