167: 				// Bail out if we're "failing-fast". Check to see if the number of failures
168: 				// has been increased by this rule (which could've generated 1 or more failures).
169: 				break;
170: 			}
171: 		}
172: 
173: 		SetExecutedRuleSets(result, context);
174: 
175: 		if (!result.IsValid && context.ThrowOnFailures) {
